TEST(SeratoCrateTreeTest, PreservesDotsAndUnicodeInNames) {
    EXPECT_EQ(cratePathComponents(QStringLiteral("/Subcrates/01. HIP-HOP%%Été 2026. Vol. 2.crate")),
            (QStringList{QStringLiteral("01. HIP-HOP"), QStringLiteral("Été 2026. Vol. 2")}));
}

TEST(SeratoCrateTreeTest, RejectsEmptyHierarchyComponents) {
    EXPECT_TRUE(cratePathComponents(QStringLiteral(".crate")).isEmpty());
    EXPECT_TRUE(cratePathComponents(QStringLiteral("Parent%%%%Child.crate")).isEmpty());
    EXPECT_TRUE(cratePathComponents(QStringLiteral("Parent%%.crate")).isEmpty());
}

TEST(SeratoCrateTreeTest, GroupsHiddenFolderWithoutDiscardingItsCrates) {
    TreeItem root;
    QHash<QString, TreeItem*> nodes;
    auto* first = appendCrate(&root,
            QStringLiteral("/Subcrates/[HIDDEN]%%90. Divers%%Samples.crate"), &nodes);
    auto* second = appendCrate(&root,
            QStringLiteral("/Subcrates/[HIDDEN]%%90. Divers%%Jingles.crate"), &nodes);
    ASSERT_EQ(root.childRows(), 1);
    auto* hidden = root.child(0);
    EXPECT_EQ(hidden->getLabel(), QStringLiteral("[HIDDEN]"));
    ASSERT_EQ(hidden->childRows(), 1);
    auto* tools = hidden->child(0);
    EXPECT_EQ(tools->getLabel(), QStringLiteral("90. Divers"));
    EXPECT_EQ(tools->childRows(), 2);
    EXPECT_EQ(first->parent(), tools);
    EXPECT_EQ(second->parent(), tools);
    EXPECT_EQ(first->getData().toList().at(0).toString(),
            QStringLiteral("/Subcrates/[HIDDEN]%%90. Divers%%Samples.crate"));
}

TEST(SeratoCrateTreeTest, ParentLoadedAfterChildKeepsBothPlaylists) {
    TreeItem root;
    QHash<QString, TreeItem*> nodes;
    auto* child = appendCrate(&root,
            QStringLiteral("/Subcrates/01. HIP-HOP%%Classics.crate"), &nodes);
    auto* parent = root.child(0);
    EXPECT_FALSE(parent->getData().isValid());
    EXPECT_EQ(appendCrate(&root, QStringLiteral("/Subcrates/01. HIP-HOP.crate"), &nodes), parent);
    EXPECT_EQ(root.childRows(), 1);
    EXPECT_EQ(parent->childRows(), 1);
    EXPECT_EQ(parent->child(0), child);
    EXPECT_EQ(parent->getData().toList().at(0).toString(),
            QStringLiteral("/Subcrates/01. HIP-HOP.crate"));
    EXPECT_TRUE(parent->getData().toList().at(1).toBool());
}

TEST(SeratoCrateTreeTest, SameLeafNameInDifferentParentsRemainsDistinct) {
    TreeItem root;
    QHash<QString, TreeItem*> nodes;
    auto* a = appendCrate(&root, QStringLiteral("A%%Classics.crate"), &nodes);
    auto* b = appendCrate(&root, QStringLiteral("B%%Classics.crate"), &nodes);
    EXPECT_NE(a, b);
    EXPECT_EQ(root.childRows(), 2);
    EXPECT_NE(a->parent(), b->parent());
}

TEST(SeratoCrateTreeTest, RepeatedCrateDoesNotDuplicateTreeNodes) {
    TreeItem root;
    QHash<QString, TreeItem*> nodes;
    auto* first = appendCrate(&root, QStringLiteral("Parent%%Child.crate"), &nodes);
    EXPECT_EQ(appendCrate(&root, QStringLiteral("Parent%%Child.crate"), &nodes), first);
    EXPECT_EQ(root.childRows(), 1);
    EXPECT_EQ(root.child(0)->childRows(), 1);
}

